$('pageexport').onclick=async()=>{if(pageSwitching)return;rememberPage();const previous=pageIndex;pageSwitching=true;try{for(let i=0;i<pageRecords.length;i++){const snapshot=validateDocument(pageRecords[i].snapshot);await restore(snapshot);render(false);const filename='photosoap-page-'+String(i+1).padStart(2,'0')+'.png';download(canvas.toDataURL('image/png'),filename)}await restore(pageRecords[previous].snapshot);pageIndex=previous;updatePagePicker()}catch(err){try{await restore(pageRecords[previous].snapshot)}catch{}pageIndex=previous;updatePagePicker();alert('Page export failed: '+err.message)}finally{pageSwitching=false;render()}};
