$('pagerename').onclick=()=>{if(pageSwitching)return;const name=prompt('Page name',pageRecords[pageIndex]?.name||'');if(name===null)return;const clean=name.trim().slice(0,80);if(!clean)return;pageRecords[pageIndex].name=clean;updatePagePicker()};
function shiftPage(delta){if(pageSwitching)return;const next=pageIndex+delta;if(next<0||next>=pageRecords.length)return;rememberPage();[pageRecords[pageIndex],pageRecords[next]]=[pageRecords[next],pageRecords[pageIndex]];pageIndex=next;updatePagePicker()}
$('pageup').onclick=()=>shiftPage(-1);
$('pagedown').onclick=()=>shiftPage(1);

