$('pageduplicate').onclick=async()=>{if(pageSwitching||pageRecords.length>=20)return;rememberPage();pageRecords.push({name:'Page '+(++pageSequence),snapshot:structuredClone(pageRecords[pageIndex].snapshot)});await switchPage(pageRecords.length-1)};
