$('text').onclick=()=>{const value=prompt('Text to add');if(!value)return;const l=addLayer('Text: '+value.slice(0,20));if(!l)return;l.textData={value,size:Math.max(8,Math.min(300,Number($('textsize').value)||64)),font:$('textfont').value,weight:$('textweight').value,align:$('textalign').value,color:$('color').value,leading:Math.max(.8,Math.min(3,Number($('textleading').value)||1.25)),tracking:Math.max(-5,Math.min(30,Number($('texttracking').value)||0))};drawTextLayer(l);refresh()}
