// Phase 5 Batch 3: local retouching operations on the active raster layer.
const retouchPanel=document.createElement('section');retouchPanel.id='retouchPanel';retouchPanel.innerHTML='<h4>Professional Retouching</h4><label>Radius <input id="retouchRadius" type="range" min="2" max="60" value="12"></label><label>Strength <input id="retouchStrength" type="range" min="1" max="100" value="55"></label><label>Target X <input id="retouchX" type="number" value="40"></label><label>Target Y <input id="retouchY" type="number" value="40"></label><label>Source X <input id="retouchSourceX" type="number" value="20"></label><label>Source Y <input id="retouchSourceY" type="number" value="20"></label><button id="retouchBlur" type="button">Smooth Spot</button><button id="retouchSharpen" type="button">Sharpen Spot</button><button id="retouchLighten" type="button">Dodge Spot</button><button id="retouchDarken" type="button">Burn Spot</button><button id="retouchClone" type="button">Clone Spot</button><button id="retouchDesaturate" type="button">Desaturate Spot</button><span id="retouchStatus" role="status"></span>';document.querySelector('main > aside').appendChild(retouchPanel);
const applyRetouch=mode=>{const l=active();if(!l||l.locked||!l.visible)return;const r=Number($('retouchRadius').value),strength=Number($('retouchStrength').value)/100,x=Math.round(Number($('retouchX').value)),y=Math.round(Number($('retouchY').value)),sx=Math.round(Number($('retouchSourceX').value)),sy=Math.round(Number($('retouchSourceY').value));if(![r,strength,x,y,sx,sy].every(Number.isFinite))return;const c=l.canvas.getContext('2d'),w=l.canvas.width,h=l.canvas.height,px=x-l.x,py=y-l.y,sourceX=sx-l.x,sourceY=sy-l.y;if(px+r<0||py+r<0||px-r>=w||py-r>=h)return;const left=Math.max(0,Math.floor(px-r)),top=Math.max(0,Math.floor(py-r)),right=Math.min(w,Math.ceil(px+r+1)),bottom=Math.min(h,Math.ceil(py+r+1)),width=right-left,height=bottom-top;if(width<=0||height<=0)return;const original=c.getImageData(0,0,w,h),out=c.createImageData(width,height),src=original.data,dst=out.data;const at=(xx,yy)=>((Math.max(0,Math.min(h-1,yy))*w+Math.max(0,Math.min(w-1,xx)))*4);checkpoint();for(let yy=0;yy<height;yy++)for(let xx=0;xx<width;xx++){const ax=left+xx,ay=top+yy,idx=at(ax,ay),di=(yy*width+xx)*4,dist=Math.hypot(ax-px,ay-py),mix=Math.max(0,1-dist/r)*strength;for(let ch=0;ch<4;ch++)dst[di+ch]=src[idx+ch];if(mix<=0||selection&&(ax+l.x<selection.x||ay+l.y<selection.y||ax+l.x>=selection.x+selection.w||ay+l.y>=selection.y+selection.h))continue;let samples=[src[idx],src[idx+1],src[idx+2]];if(mode==='clone'){const sample=at(Math.round(sourceX+ax-px),Math.round(sourceY+ay-py));samples=[src[sample],src[sample+1],src[sample+2]]}else if(mode==='blur'||mode==='sharpen'){let sum=[0,0,0],count=0;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const p=at(ax+dx,ay+dy);for(let ch=0;ch<3;ch++)sum[ch]+=src[p+ch];count++}samples=sum.map((v,ch)=>mode==='blur'?v/count:Math.max(0,Math.min(255,2*src[idx+ch]-v/count)))}else if(mode==='lighten')samples=samples.map(v=>v+(255-v)*.45);else if(mode==='darken')samples=samples.map(v=>v*.55);else if(mode==='desaturate'){const gray=.2126*samples[0]+.7152*samples[1]+.0722*samples[2];samples=[gray,gray,gray]}for(let ch=0;ch<3;ch++)dst[di+ch]=Math.round(src[idx+ch]*(1-mix)+samples[ch]*mix)}c.putImageData(out,left,top);refresh();$('retouchStatus').textContent=mode+' applied'};
for(const [id,mode] of [['retouchBlur','blur'],['retouchSharpen','sharpen'],['retouchLighten','lighten'],['retouchDarken','darken'],['retouchClone','clone'],['retouchDesaturate','desaturate']])$(id).onclick=()=>applyRetouch(mode);

