// Phase 5 Batch 6: deterministic on-device intelligent adjustment suggestions.
const smartPanel=document.createElement('section');smartPanel.id='smartAdjustPanel';smartPanel.innerHTML='<h4>Smart Photo Adjust</h4><button id="smartAnalyze" type="button">Analyze Layer</button><button id="smartAutoTone" type="button">Auto Tone</button><button id="smartAutoContrast" type="button">Auto Contrast</button><button id="smartAutoColor" type="button">Auto Color</button><button id="smartAutoExposure" type="button">Auto Exposure</button><button id="smartReset" type="button">Reset Smart Adjustments</button><span id="smartStatus" role="status">Ready</span>';document.querySelector('main > aside').appendChild(smartPanel);
const analyzeLayer=()=>{const l=active();if(!l)return null;const c=l.canvas,w=c.width,h=c.height,ctx=c.getContext('2d'),data=ctx.getImageData(0,0,w,h).data;let count=0,sum=0,min=255,max=0,r=0,g=0,b=0;const stride=Math.max(1,Math.floor(w*h/25000));for(let i=0;i<w*h;i+=stride){const k=i*4;if(data[k+3]<10)continue;const lum=.2126*data[k]+.7152*data[k+1]+.0722*data[k+2];sum+=lum;min=Math.min(min,lum);max=Math.max(max,lum);r+=data[k];g+=data[k+1];b+=data[k+2];count++}return count?{mean:sum/count,min,max,r:r/count,g:g/count,b:b/count}:null};
$('smartAnalyze').onclick=()=>{const a=analyzeLayer();$('smartStatus').textContent=a?'Mean brightness '+Math.round(a.mean)+' · contrast '+Math.round(a.max-a.min):'No visible pixels'};
const smartApply=mode=>{const l=active();if(!l||l.locked)return;const a=analyzeLayer();if(!a){$('smartStatus').textContent='No visible pixels';return}checkpoint();if(mode==='tone'){l.brightness=Math.round(Math.max(60,Math.min(160,100+(128-a.mean)*.3)));l.contrast=Math.round(Math.max(75,Math.min(160,100+(180-(a.max-a.min))*.25)))}if(mode==='contrast')l.contrast=Math.round(Math.max(80,Math.min(170,100+(210-(a.max-a.min))*.3)));if(mode==='exposure')l.exposure=Math.round(Math.max(65,Math.min(165,100*128/Math.max(20,a.mean))));if(mode==='color'){l.saturation=Math.round(Math.max(80,Math.min(135,100+(Math.max(a.r,a.g,a.b)-Math.min(a.r,a.g,a.b)<20?12:0))));l.warmth=Math.round(Math.max(-50,Math.min(50,(a.b-a.r)*.35)))}refresh();$('smartStatus').textContent='Auto '+mode+' applied (editable)'};
