const modifyVector=fn=>{const l=vectorTarget();if(!l||l.locked)return;const d=l.shapeData||l.elementData,next=fn({...d});if(!next||![next.x,next.y,next.w,next.h,next.rotation||0].every(Number.isFinite)||next.w<=0||next.h<=0||[next.x,next.y,next.w,next.h].some(v=>Math.abs(v)>12000))return;checkpoint();if(l.shapeData){l.shapeData=next;drawShapeLayer(l)}else{l.elementData=next;drawElementLayer(l)}refresh();syncVector()};
