// Phase 5 Batch 8: editable starter design templates.
const templatePanel=document.createElement('section');templatePanel.id='designTemplatePanel';templatePanel.innerHTML='<h4>Design Templates</h4><label>Template <select id="designTemplate"><option value="poster">Event Poster</option><option value="social">Social Announcement</option><option value="quote">Quote Card</option><option value="sale">Sale Promotion</option></select></label><label>Headline <input id="templateHeadline" maxlength="120" value="YOUR HEADLINE"></label><label>Subtitle <input id="templateSubtitle" maxlength="120" value="Your message goes here"></label><label>Accent <input id="templateAccent" type="color" value="#4f46e5"></label><button id="templateInsert" type="button">Insert Editable Template</button><span id="templateStatus" role="status"></span>';document.querySelector('main > aside').appendChild(templatePanel);
$('templateInsert').onclick=()=>{const kind=$('designTemplate').value,headline=$('templateHeadline').value.slice(0,120),subtitle=$('templateSubtitle').value.slice(0,120),accent=$('templateAccent').value;if(layers.length+4>MAX_LAYERS||(layers.length+4)*canvas.width*canvas.height>48000000){$('templateStatus').textContent='Layer limit reached';return}const schemes={poster:['#101827','#ffffff'],social:['#eef2ff','#1e1b4b'],quote:['#fef3c7','#78350f'],sale:['#111827','#f9fafb']},colors=schemes[kind]||schemes.poster;const rect=(name,x,y,w,h,color)=>{const l=addLayer(name);if(!l)return null;l.shapeData={kind:'rectangle',x,y,w,h,color,stroke:1};drawShapeLayer(l);return l};const label=(name,value,size,color,y)=>{const l=addLayer(name);if(!l)return null;l.textData={value,color,size,font:'Arial',weight:'bold',align:'center',leading:1.2,tracking:0};l.y=y-60;drawTextLayer(l);return l};const w=canvas.width,h=canvas.height;rect('Template background',0,0,w,h,colors[0]);rect('Template accent',Math.round(w*.08),Math.round(h*.15),Math.round(w*.84),Math.max(12,Math.round(h*.04)),accent);label('Template headline',headline||'YOUR HEADLINE',Math.max(18,Math.min(70,Math.round(w*.07))),colors[1],Math.round(h*.35));label('Template subtitle',subtitle||'Your message goes here',Math.max(14,Math.min(32,Math.round(w*.035))),colors[1],Math.round(h*.58));refresh();$('templateStatus').textContent='Editable '+kind+' template inserted'};

// Phase 5 Batch 9: configurable image export studio.
const exportPanel=document.createElement('section');exportPanel.id='exportStudioPanel';exportPanel.innerHTML='<h4>Export Studio</h4><label>Filename <input id="exportFilename" value="photosoap-design" maxlength="80"></label><label>Format <select id="exportFormat"><option value="png">PNG</option><option value="jpeg">JPEG</option><option value="webp">WebP</option></select></label><label>Scale <select id="exportScale"><option value="1">1×</option><option value="2">2×</option><option value="0.5">0.5×</option></select></label><label>Quality <input id="exportQuality" type="range" min="10" max="100" value="90"></label><label>JPEG background <input id="exportBackground" type="color" value="#ffffff"></label><button id="exportPreview" type="button">Preview Export</button><button id="exportDownload" type="button">Download Image</button><span id="exportStatus" role="status"></span>';document.querySelector('main > aside').appendChild(exportPanel);
const buildExport=()=>{const format=$('exportFormat').value,scale=Number($('exportScale').value),quality=Number($('exportQuality').value)/100,w=Math.max(1,Math.round(canvas.width*scale)),h=Math.max(1,Math.round(canvas.height*scale));if(w*h>24000000)throw Error('Export exceeds 24 megapixels');render(false);try{const out=document.createElement('canvas');out.width=w;out.height=h;const c=out.getContext('2d');if(format==='jpeg'){c.fillStyle=$('exportBackground').value;c.fillRect(0,0,w,h)}c.drawImage(canvas,0,0,w,h);const mime=format==='jpeg'?'image/jpeg':format==='webp'?'image/webp':'image/png',data=out.toDataURL(mime,quality);if(!data.startsWith('data:'+mime))throw Error('This browser does not support '+format.toUpperCase()+' export');return {data,w,h,format}}finally{render()}};
$('exportPreview').onclick=()=>{try{const e=buildExport();$('exportStatus').textContent=e.w+' × '+e.h+' px · '+e.format.toUpperCase()}catch(err){$('exportStatus').textContent=err.message}};
$('exportDownload').onclick=()=>{try{const e=buildExport(),name=($('exportFilename').value.trim()||'photosoap-design').replace(/[^a-z0-9 _-]/gi,'_').slice(0,80);download(e.data,name+'.'+(e.format==='jpeg'?'jpg':e.format));$('exportStatus').textContent='Exported '+e.w+' × '+e.h+' px'}catch(err){$('exportStatus').textContent=err.message}};

// Phase 5 Batch 10: document health checks and local recovery controls.
const healthPanel=document.createElement('section');healthPanel.id='documentHealthPanel';healthPanel.innerHTML='<h4>Document Health</h4><button id="healthCheck" type="button">Check Document</button><button id="healthBackup" type="button">Download Recovery Backup</button><button id="healthAutosave" type="button">Save Recovery Snapshot</button><span id="healthStatus" role="status" aria-live="polite"></span>';document.querySelector('main > aside').appendChild(healthPanel);
const inspectDocument=()=>{const problems=[];if(!canvas.width||!canvas.height||canvas.width*canvas.height>24000000)problems.push('Invalid canvas size');if(layers.length>MAX_LAYERS)problems.push('Layer limit exceeded');const ids=new Set();for(const l of layers){if(!l||!l.canvas||l.canvas.width!==canvas.width||l.canvas.height!==canvas.height)problems.push('Layer canvas mismatch');if(!l||!l.id||ids.has(l.id))problems.push('Duplicate or missing layer ID');if(l&&l.id)ids.add(l.id);if(l&&(!Number.isFinite(l.opacity)||l.opacity<0||l.opacity>1))problems.push('Invalid opacity');if(l&&(!Number.isFinite(l.x)||!Number.isFinite(l.y)))problems.push('Invalid layer position')}if(selected&&!ids.has(selected))problems.push('Selected layer missing');return {ok:problems.length===0,problems,layerCount:layers.length,width:canvas.width,height:canvas.height}};
$('healthCheck').onclick=()=>{const r=inspectDocument();$('healthStatus').textContent=r.ok?'PASS: '+r.layerCount+' layers, '+r.width+' × '+r.height+' px': 'ISSUES: '+r.problems.join('; ')};
$('healthBackup').onclick=()=>{try{rememberPage();const data=JSON.stringify({format:'photosoap',version:3,activePage:pageIndex,pages:pageRecords.map(p=>({name:p.name,document:p.snapshot}))});const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));download(url,'photosoap-recovery-backup.json');setTimeout(()=>URL.revokeObjectURL(url),10000);$('healthStatus').textContent='Recovery backup downloaded'}catch(e){$('healthStatus').textContent='Backup failed: '+e.message}};
$('healthAutosave').onclick=()=>{try{localStorage.setItem('photosoap-manual-recovery',JSON.stringify(capture()));$('healthStatus').textContent='Local recovery snapshot saved'}catch(e){$('healthStatus').textContent='Local storage unavailable: '+e.message}};

// Phase 6 Batch 1: precision selection utilities (rectangular selection model).
const precisionPanel=document.createElement('section');precisionPanel.id='selectionPrecisionPanel';precisionPanel.innerHTML='<h4>Selection Precision</h4><label>Step (px) <input id="precisionStep" type="number" min="1" max="500" value="10"></label><button id="precisionLeft">Move Left</button><button id="precisionRight">Move Right</button><button id="precisionUp">Move Up</button><button id="precisionDown">Move Down</button><button id="precisionExpand">Expand</button><button id="precisionContract">Contract</button><button id="precisionHorizontal">Horizontal Half</button><button id="precisionVertical">Vertical Half</button><button id="precisionSquare">Square Selection</button><button id="precisionFull">Full Canvas</button><span id="precisionStatus" role="status"></span>';document.querySelector('main > aside').appendChild(precisionPanel);
const precisionStep=()=>Math.max(1,Math.min(500,Math.round(Number($('precisionStep').value)||1)));
const precisionApply=fn=>{if(!selection){$('precisionStatus').textContent='Create a selection first';return}const r=clampSelection(selection.x,selection.y,selection.w,selection.h),next=fn(r,precisionStep());if(!next)return;setAdvancedSelection(next);$('precisionStatus').textContent='Selection updated'};
for(const [id,dx,dy] of [['precisionLeft',-1,0],['precisionRight',1,0],['precisionUp',0,-1],['precisionDown',0,1]])$(id).onclick=()=>precisionApply((r,step)=>({...r,x:Math.max(0,Math.min(canvas.width-r.w,r.x+dx*step)),y:Math.max(0,Math.min(canvas.height-r.h,r.y+dy*step))}));
$('precisionExpand').onclick=()=>precisionApply((r,n)=>{const x=Math.max(0,r.x-n),y=Math.max(0,r.y-n);return {x,y,w:Math.min(canvas.width-x,r.x+r.w+n-x),h:Math.min(canvas.height-y,r.y+r.h+n-y)}});
$('precisionContract').onclick=()=>precisionApply((r,n)=>r.w>2*n&&r.h>2*n?{x:r.x+n,y:r.y+n,w:r.w-2*n,h:r.h-2*n}:null);
$('precisionHorizontal').onclick=()=>precisionApply(r=>({...r,h:Math.max(1,Math.floor(r.h/2))}));
$('precisionVertical').onclick=()=>precisionApply(r=>({...r,w:Math.max(1,Math.floor(r.w/2))}));
$('precisionSquare').onclick=()=>precisionApply(r=>({...r,w:Math.min(r.w,r.h),h:Math.min(r.w,r.h)}));
$('precisionFull').onclick=()=>setAdvancedSelection({x:0,y:0,w:canvas.width,h:canvas.height});

// Phase 6 Batch 2: professional layer workflow operations.
const layerOps=document.createElement('section');layerOps.id='layerOperationsPanel';layerOps.innerHTML='<h4>Layer Operations</h4><label>Rename <input id="layerOpsName" maxlength="100" placeholder="Layer name"></label><button id="layerOpsRename">Rename</button><button id="layerOpsDuplicate">Duplicate</button><button id="layerOpsHide">Toggle Visibility</button><button id="layerOpsLock">Toggle Lock</button><button id="layerOpsTop">Bring to Front</button><button id="layerOpsBottom">Send to Back</button><button id="layerOpsUp">Move Up</button><button id="layerOpsDown">Move Down</button><button id="layerOpsFullOpacity">Full Opacity</button><button id="layerOpsHalfOpacity">Half Opacity</button><span id="layerOpsStatus" role="status"></span>';document.querySelector('main > aside').appendChild(layerOps);
const layerOp=(fn,allowLocked=false)=>{const l=active();if(!l||(!allowLocked&&l.locked)){$('layerOpsStatus').textContent='Select an unlocked layer';return}checkpoint();fn(l);refresh();$('layerOpsStatus').textContent='Layer updated'};
$('layerOpsRename').onclick=()=>{const name=$('layerOpsName').value.trim().slice(0,100);if(name)layerOp(l=>l.name=name)};
$('layerOpsHide').onclick=()=>layerOp(l=>l.visible=!l.visible,true);
$('layerOpsLock').onclick=()=>layerOp(l=>l.locked=!l.locked,true);
$('layerOpsTop').onclick=()=>layerOp(l=>{layers.splice(layers.indexOf(l),1);layers.push(l)});
$('layerOpsBottom').onclick=()=>layerOp(l=>{layers.splice(layers.indexOf(l),1);layers.unshift(l)});
$('layerOpsUp').onclick=()=>layerOp(l=>{const i=layers.indexOf(l);if(i<layers.length-1)[layers[i],layers[i+1]]=[layers[i+1],layers[i]]});
$('layerOpsDown').onclick=()=>layerOp(l=>{const i=layers.indexOf(l);if(i>0)[layers[i],layers[i-1]]=[layers[i-1],layers[i]]});
$('layerOpsFullOpacity').onclick=()=>layerOp(l=>l.opacity=1);
$('layerOpsHalfOpacity').onclick=()=>layerOp(l=>l.opacity=.5);
$('layerOpsDuplicate').onclick=()=>{const l=active();if(!l||layers.length>=MAX_LAYERS||(layers.length+1)*canvas.width*canvas.height>48000000){$('layerOpsStatus').textContent='Layer limit reached or no layer selected';return}checkpoint();const copy={...l,id:++counter,name:l.name+' copy',canvas:document.createElement('canvas'),locked:false};copy.canvas.width=canvas.width;copy.canvas.height=canvas.height;copy.canvas.getContext('2d').drawImage(l.canvas,0,0);if(l.shapeData)copy.shapeData={...l.shapeData};if(l.elementData)copy.elementData={...l.elementData};if(l.textData)copy.textData={...l.textData};if(l.selectionMask)copy.selectionMask={...l.selectionMask};if(l.layerStyles)copy.layerStyles=JSON.parse(JSON.stringify(l.layerStyles));if(l.brushMaskStrokes)copy.brushMaskStrokes=JSON.parse(JSON.stringify(l.brushMaskStrokes));layers.splice(layers.indexOf(l)+1,0,copy);selected=copy.id;refresh();$('layerOpsStatus').textContent='Layer duplicated'};

// Phase 6 Batch 3: rectangular mask precision and compositing operations.
const maskPrecision=document.createElement('section');maskPrecision.id='maskPrecisionPanel';maskPrecision.innerHTML='<h4>Mask Precision</h4><button id="maskPrecCreate">Create Full Mask</button><button id="maskPrecToggle">Toggle Mask</button><button id="maskPrecInvert">Invert Mask</button><button id="maskPrecFeatherUp">Feather +5</button><button id="maskPrecFeatherDown">Feather -5</button><button id="maskPrecGrow">Grow 10px</button><button id="maskPrecShrink">Shrink 10px</button><button id="maskPrecCenter">Center Mask</button><button id="maskPrecCopy">Copy to Layer Above</button><button id="maskPrecRemove">Remove Mask</button><span id="maskPrecStatus" role="status"></span>';document.querySelector('main > aside').appendChild(maskPrecision);
const editMask=(fn,create=false)=>{const l=active();if(!l||l.locked||(!l.selectionMask&&!create)){$('maskPrecStatus').textContent='Select an unlocked layer with a mask';return}checkpoint();const m=l.selectionMask||{x:0,y:0,w:canvas.width,h:canvas.height,enabled:true,feather:0,inverted:false};l.selectionMask=fn({...m},l);refresh();$('maskPrecStatus').textContent='Mask updated'};
$('maskPrecCreate').onclick=()=>editMask(m=>m,true);
$('maskPrecToggle').onclick=()=>editMask(m=>({...m,enabled:m.enabled===false}));
$('maskPrecInvert').onclick=()=>editMask(m=>({...m,inverted:!m.inverted}));
$('maskPrecFeatherUp').onclick=()=>editMask(m=>({...m,feather:Math.min(100,(m.feather||0)+5)}));
$('maskPrecFeatherDown').onclick=()=>editMask(m=>({...m,feather:Math.max(0,(m.feather||0)-5)}));
$('maskPrecGrow').onclick=()=>editMask(m=>{const x=Math.max(0,m.x-10),y=Math.max(0,m.y-10);return {...m,x,y,w:Math.min(canvas.width-x,m.x+m.w+10-x),h:Math.min(canvas.height-y,m.y+m.h+10-y)}});
$('maskPrecShrink').onclick=()=>editMask(m=>{const n=Math.min(10,Math.floor((m.w-1)/2),Math.floor((m.h-1)/2));return {...m,x:m.x+n,y:m.y+n,w:m.w-2*n,h:m.h-2*n}});
$('maskPrecCenter').onclick=()=>editMask(m=>({...m,x:Math.max(0,Math.round((canvas.width-m.w)/2)),y:Math.max(0,Math.round((canvas.height-m.h)/2))}));
$('maskPrecCopy').onclick=()=>{const l=active(),i=layers.indexOf(l),above=layers[i+1];if(!l?.selectionMask||!above||above.locked){$('maskPrecStatus').textContent='No eligible layer above';return}checkpoint();above.selectionMask={...l.selectionMask};refresh();$('maskPrecStatus').textContent='Mask copied'};
$('maskPrecRemove').onclick=()=>{const l=active();if(!l?.selectionMask||l.locked)return;checkpoint();delete l.selectionMask;refresh();$('maskPrecStatus').textContent='Mask removed'};

// Phase 6 Batch 4: ten repeatable brush configuration presets.
const brushLibrary=document.createElement('section');brushLibrary.id='brushLibraryPanel';brushLibrary.innerHTML='<h4>Brush Library</h4><label>Preset <select id="brushLibrarySelect"><option value="pencil">Pencil</option><option value="marker">Marker</option><option value="airbrush">Airbrush</option><option value="pixel">Pixel Art</option><option value="calligraphy">Calligraphy</option><option value="soft">Soft Round</option><option value="hard">Hard Round</option><option value="sketch">Sketch</option><option value="highlighter">Highlighter</option><option value="eraser">Eraser Setup</option></select></label><button id="brushLibraryApply">Apply Preset</button><span id="brushLibraryStatus" role="status"></span>';document.querySelector('main > aside').appendChild(brushLibrary);
const brushLibraryPresets={pencil:[3,90,100,10,'round'],marker:[24,80,100,15,'round'],airbrush:[65,20,10,10,'round'],pixel:[8,100,100,100,'square'],calligraphy:[18,90,100,20,'square'],soft:[35,65,15,10,'round'],hard:[35,100,100,20,'round'],sketch:[5,40,70,25,'round'],highlighter:[35,25,100,20,'square'],eraser:[25,100,100,20,'round']};
$('brushLibraryApply').onclick=()=>{const key=$('brushLibrarySelect').value,p=brushLibraryPresets[key];if(!p)return;$('size').value=p[0];$('brushOpacity').value=p[1];$('brushHardness').value=p[2];$('brushSpacing').value=p[3];$('brushPreset').value=p[4];syncBrushSettings();$('brushLibraryStatus').textContent='Applied '+key+' preset'+(key==='eraser'?' (select Eraser tool to erase)':'')};

/* Phase 6 Batch 5: ten reversible retouch adjustment recipes. */
const retouchRecipesPanelElement=document.createElement('section');retouchRecipesPanelElement.id='retouchRecipesPanel';retouchRecipesPanelElement.innerHTML='<h4>Retouch Recipes</h4><label>Recipe <select id="retouchRecipe"><option value="portrait">Soft Portrait</option><option value="clarity">Detail Clarity</option><option value="warm">Warm Tone</option><option value="cool">Cool Tone</option><option value="highlight">Highlight Recovery</option><option value="shadow">Shadow Lift</option><option value="vivid">Vivid Color</option><option value="matte">Matte Finish</option><option value="mono">Monochrome</option><option value="neutral">Neutral Reset</option></select></label><button id="retouchApply">Apply</button><span id="retouchStatus" role="status"></span>';document.querySelector('main > aside').appendChild(retouchRecipesPanelElement);
const retouchDefaults={brightness:100,contrast:100,saturation:100,warmth:0,shadows:100,highlights:100,vibrance:100,fade:0,grayscale:0,softFocus:0,clarity:0};
const retouchRecipes={portrait:{contrast:95,saturation:105,softFocus:2},clarity:{contrast:108,clarity:20},warm:{warmth:15,saturation:105},cool:{warmth:-15},highlight:{highlights:80},shadow:{shadows:120},vivid:{saturation:115,vibrance:120},matte:{contrast:90,fade:15},mono:{grayscale:100,contrast:110},neutral:{}};
$('retouchApply').onclick=()=>{const l=active(),key=$('retouchRecipe').value,recipe=retouchRecipes[key];if(!l||l.locked||!recipe){$('retouchStatus').textContent='Select an unlocked layer';return}checkpoint();for(const [name,value] of Object.entries(retouchDefaults))l[name]=Object.hasOwn(recipe,name)?recipe[name]:value;refresh();$('retouchStatus').textContent='Applied '+key+' recipe (undo available)'};


